SELECT DISTINCT a.BOOKSET_ID booksetId,/**A.账套代码**/ b.BUSI_ID busiId,/**A.业务明细代码**/ a.SUBJECT_NO subjectNo,/**A.科目号**/ a.DETAIL_SUBJECT_NO detailSubjectNo,/**A.四级科目号**/ b.BUSI_DETAIL_TYPE busiDetailType,/**B.业务明细代码类型**/ b.DETAIL_SUBJECT_NO_TAIL detailSubjectNoTail,/**B.四级科目尾号**/ b.DETAIL_SUBNAME_TAIL detailSubnameTail,/**B.四级科目尾号名称**/ a.BOK_DETAIL_ID bokDetailId,/**A.账务明细代码**/ b.BRANCH branch,/**B.分支序号**/ d.SUBJECT_NAME subjectName/**D.科目名称**/ FROM BOK_BOOKDETAIL_CURRENT a LEFT JOIN BOK_DETAIL_ID b ON a.BOOKSET_ID = b.BOOKSET_ID AND a.BOK_DETAIL_ID = b.BOK_DETAIL_ID LEFT JOIN BOK_BOOKSET c ON a.bookset_id = c.bookset_id LEFT JOIN BOK_SUBJECT d ON c.BOOKSET_ID_TMPL = d.BOOKSET_ID AND a.SUBJECT_NO = d.SUBJECT_NO LEFT JOIN ( select fp.FINPROD_ID as finprodId,/**金融产品代码 **/ fp.FINPROD_TYPE as finprodType,/** 金融产品类型**/ fp.TRADE_MARKET as tradeMarket,/** 交易场所**/ fpa.IS_QTZQ as isQtzq,/**是否其他债券 **/ fpt.TYPE_1 as type1,/** 分类1**/ fpt.TYPE_2 as type2/** 分类2**/ from FIN_PRODUCT fp/** 标的类金融产品表**/ left join FIN_PRODUCT_TYPE fpt/** 金融产品分类表**/ on fpt.FINPROD_ID = fp.FINPROD_ID left join FIN_PRODUCT_ADD fpa/**标的类金融产品附属表 **/ on fpa.FINPROD_ID = fp.FINPROD_ID where fp.FINPROD_TYPE != 'F18'
union all
select fi.FINPROD_ID as finprodId,/**金融产品代码 **/ fi.FINPROD_TYPE as finprodType,/** 金融产品类型**/ fi.TRADE_MARKET as tradeMarket,/** 交易场所**/ null as isQtzq,/**是否其他债券 **/ fy.TYPE_1 as type1,/** 分类1**/ fy.TYPE_2 as type2/** 分类2**/ from FIN_TRADE_PRODUCT fi/**交易类金融产品表 **/ left join FIN_PRODUCT_TYPE fy/** 金融产品分类表**/ on fi.FINPROD_ID = fy.FINPROD_ID and fi.BRANCH = fy.BRANCH where fi.BRANCH = 0 and fi.FINPROD_TYPE != 'F21' ) bdxx on bdxx.finprodId = b.BUSI_ID and bdxx.finprodType = b.BUSI_DETAIL_TYPE WHERE a.SUBJECT_NO in
#{item}
and bdxx.finprodType = #{finprodType,jdbcType=VARCHAR}
and bdxx.tradeMarket = #{tradeMarket,jdbcType=VARCHAR}
and bdxx.type2 = #{type2,jdbcType=VARCHAR}
and bdxx.isQtzq = #{isQtzq,jdbcType=VARCHAR}
and (bdxx.isQtzq = #{isQtzq,jdbcType=VARCHAR} or bdxx.isQtzq is null)
/**考虑Oracle中的in超过1000的处理**/
AND (c.BOOKSET_ID_TMPL IN
null) or c.BOOKSET_ID_TMPL IN (
#{item, jdbcType=VARCHAR}
)
/**考虑Oracle中的in超过1000的处理**/
AND (a.BOOKSET_ID IN
null) or a.BOOKSET_ID IN (
#{item, jdbcType=VARCHAR}
)
AND a.BOOKSET_ID = #{booksetId, jdbcType=VARCHAR}

